package io.reductxn.api.port.in;

import java.time.Instant;
import java.util.Objects;

/**
 * The invitation a request produced, as the contract's `Invite` schema describes it.
 *
 * <p>{@code code} is generated by the store rather than by this layer, and the reason is the constraint: a code must be
 * unique across the deployment, so uniqueness is something only the store can establish - it holds the primary key and
 * can retry a collision, and a generator here would be guessing at what the database is going to say. What the layer
 * does know is the *alphabet and length*, which the table's CHECK constraint fixes, and the store generates within them.
 *
 * <p>{@code maxUses} is null when the invitation has no limit, which is the contract's optional field absent rather than
 * zero. There is no {@code groupId} here even though the store knows it: the schema this answers has no such field, and
 * a caller who created the code already knows which group it is for.
 *
 * @param code      the code itself, to be read out loud or copied
 * @param expiresAt when it stops joining anybody
 * @param maxUses   how many times it may be spent, or null for no limit
 */
public record CreatedInvite(String code, Instant expiresAt, Integer maxUses) {

    public CreatedInvite {
        Objects.requireNonNull(code, "code");
        Objects.requireNonNull(expiresAt, "expiresAt");
    }
}
